import Head from 'next/head';
import { MongoClient } from 'mongodb';

function parseCookies(cookieHeader) {
  const list = {};
  if (!cookieHeader) return list;
  cookieHeader.split(';').forEach(function(cookie) {
    const parts = cookie.split('=');
    const key = parts.shift().trim();
    const value = decodeURI(parts.join('='));
    list[key] = value;
  });
  return list;
}

function AuthorizePage({ user, messages = [], error }) {
  return (
    <>
      <Head>
        <title>Authorized Page</title>
      </Head>
      <main style={{ padding: 20 }}>
        <h1>Authorized content</h1>
        <p>Welcome{user ? `, ${user}` : ''}! You have access to this protected page.</p>

        <p>
          To sign out, <a href="/api/logout">click here to logout</a> and then refresh.
        </p>

        <section style={{ marginTop: 24 }}>
          <h2>Latest messages</h2>
          {error && <p style={{ color: 'red' }}>{error}</p>}
          {messages.length === 0 && <p>No messages yet.</p>}
          <ul>
            {messages.map((m) => (
              <li key={m.id} style={{ marginBottom: 12, borderBottom: '1px solid #eee', paddingBottom: 8 }}>
                <div><strong>{m.name}</strong> &lt;{m.email}&gt;</div>
                <div style={{ whiteSpace: 'pre-wrap' }}>{m.message}</div>
              </li>
            ))}
          </ul>
        </section>
      </main>
    </>
  );
}

export async function getServerSideProps(context) {
  const { req } = context;
  const cookies = parseCookies(req.headers.cookie || '');

  // Compare cookie value with server-side secret
  const authToken = process.env.AUTH_TOKEN;

  if (!authToken || !cookies.auth || cookies.auth !== authToken) {
    // Not authorized -> redirect to login page
    return {
      redirect: {
        destination: '/login',
        permanent: false,
      },
    };
  }

  // Fetch latest messages from MongoDB (latest first), limit 10
  const connectionString = `mongodb+srv://${process.env.MONGODB_USERNAME}:${process.env.MONGODB_PASSWORD}@cluster0.78neqdm.mongodb.net/?retryWrites=true&w=majority&appName=Cluster0`;
  let messages = [];
  let error = null;

  try {
    const client = await MongoClient.connect(connectionString);
    const db = client.db();
    const docs = await db.collection('messages')
      .find()
      .sort({ _id: -1 })
      .limit(10)
      .toArray();

    messages = docs.map((d) => ({ id: d._id.toString(), name: d.name, email: d.email, message: d.message }));
    client.close();
  } catch {
    error = 'Could not load messages.';
  }

  return {
    props: {
      user: 'Authorized User',
      messages,
      error,
    },
  };
}

export default AuthorizePage;
